-- 106_historical_project_intelligence.sql
-- Roadmap I.51-I.58: comparable projects, benchmarks, accuracy, patterns,
-- contractor performance and future budget intelligence from sealed evidence only.
BEGIN;
CREATE OR REPLACE FUNCTION public.get_historical_project_intelligence(p_project_id bigint)RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER STABLE SET search_path=public AS $$
DECLARE u uuid:=auth.uid();target public.historical_project_records%ROWTYPE;sample_count integer;comparables jsonb;costs jsonb;durations jsonb;budget_accuracy numeric;forecast_accuracy numeric;patterns jsonb;contractors jsonb;median_ratio numeric;
BEGIN IF u IS NULL OR public.can_access_project(p_project_id)IS NOT TRUE THEN RAISE EXCEPTION'HISTORICAL_INTELLIGENCE_FORBIDDEN'USING ERRCODE='42501';END IF;SELECT*INTO target FROM public.historical_project_records WHERE project_id=p_project_id;IF target.id IS NULL THEN RAISE EXCEPTION'HISTORICAL_INTELLIGENCE_REQUIRES_SEALED_PROJECT'USING ERRCODE='55000';END IF;
WITH eligible AS(SELECT h.* FROM public.historical_project_records h WHERE h.ontology_version_id IS NOT DISTINCT FROM target.ontology_version_id AND public.can_access_project(h.project_id))SELECT count(*),COALESCE(jsonb_agg(jsonb_build_object('projectId',project_id,'projectName',payload#>>'{project,shopping_mall_name}','storeCode',payload#>>'{project,store_code}','finalCost',payload#>>'{cost,final_cost}','awardValue',payload#>>'{cost,award_value}','completionVarianceDays',payload#>>'{schedule,completion_variance_days}','contractor',payload#>>'{contractorScorecard,contractor_name}','contractorScore',payload#>>'{contractorScorecard,overall_score}')ORDER BY sealed_at DESC),'[]')INTO sample_count,comparables FROM eligible;
WITH e AS(SELECT(payload#>>'{cost,final_cost}')::numeric final_cost,(payload#>>'{cost,award_value}')::numeric award_value,(payload#>>'{cost,approved_budget}')::numeric budget,(payload#>>'{cost,latest_forecast}')::numeric forecast,(payload#>>'{schedule,completion_variance_days}')::numeric duration_variance FROM public.historical_project_records WHERE ontology_version_id IS NOT DISTINCT FROM target.ontology_version_id AND public.can_access_project(project_id)),stats AS(SELECT percentile_cont(.5)WITHIN GROUP(ORDER BY final_cost)median_final,avg(final_cost)avg_final,min(final_cost)min_final,max(final_cost)max_final,percentile_cont(.5)WITHIN GROUP(ORDER BY duration_variance)median_duration,avg(duration_variance)avg_duration,avg(abs(final_cost-budget)*100/NULLIF(budget,0))budget_error,avg(abs(final_cost-forecast)*100/NULLIF(forecast,0))forecast_error,percentile_cont(.5)WITHIN GROUP(ORDER BY final_cost/NULLIF(award_value,0))ratio FROM e)SELECT jsonb_build_object('medianFinalCost',median_final,'averageFinalCost',round(avg_final,2),'minimumFinalCost',min_final,'maximumFinalCost',max_final),jsonb_build_object('medianCompletionVarianceDays',median_duration,'averageCompletionVarianceDays',round(avg_duration,2)),round(100-LEAST(COALESCE(budget_error,100),100),2),round(100-LEAST(COALESCE(forecast_error,100),100),2),ratio INTO costs,durations,budget_accuracy,forecast_accuracy,median_ratio FROM stats;
SELECT COALESCE(jsonb_agg(jsonb_build_object('reasonCode',reason_code,'variationCount',variation_count,'approvedValue',approved_value)ORDER BY variation_count DESC),'[]')INTO patterns FROM(SELECT reason->>'reasonCode'reason_code,sum((reason->>'variationCount')::integer)variation_count,sum((reason->>'approvedValue')::numeric)approved_value FROM public.historical_project_records h CROSS JOIN LATERAL jsonb_array_elements(h.payload#>'{variations,main_reasons}')reason WHERE h.ontology_version_id IS NOT DISTINCT FROM target.ontology_version_id AND public.can_access_project(h.project_id)GROUP BY reason->>'reasonCode')x;
SELECT COALESCE(jsonb_agg(jsonb_build_object('contractorName',name,'projectCount',projects,'averageScore',round(score,2))ORDER BY score DESC),'[]')INTO contractors FROM(SELECT payload#>>'{contractorScorecard,contractor_name}'name,count(*)projects,avg((payload#>>'{contractorScorecard,overall_score}')::numeric)score FROM public.historical_project_records h WHERE h.ontology_version_id IS NOT DISTINCT FROM target.ontology_version_id AND public.can_access_project(h.project_id)GROUP BY payload#>>'{contractorScorecard,contractor_name}')x;
RETURN jsonb_build_object('projectId',p_project_id,'evidenceSource','SEALED_HISTORICAL_PROJECT_RECORDS','sampleSize',sample_count,'comparableProjects',comparables,'costBenchmarks',costs,'durationBenchmarks',durations,'budgetAccuracyScore',budget_accuracy,'forecastAccuracyScore',forecast_accuracy,'variationPatterns',patterns,'contractorPerformance',contractors,'futureBudgetIntelligence',jsonb_build_object('recommendedAwardToFinalFactor',round(COALESCE(median_ratio,1),4),'confidence',CASE WHEN sample_count>=10 THEN'HIGH'WHEN sample_count>=3 THEN'MEDIUM'ELSE'LOW'END,'sampleSize',sample_count,'warning',CASE WHEN sample_count<3 THEN'Insufficient comparable history; use as directional evidence only.'ELSE NULL END));END;$$;
REVOKE ALL ON FUNCTION public.get_historical_project_intelligence(bigint)FROM PUBLIC,anon,authenticated,service_role;GRANT EXECUTE ON FUNCTION public.get_historical_project_intelligence(bigint)TO authenticated;COMMIT;
